mapper.update:
UPDATE settle_run SET status = #{to}, version = version + 1
  , abnormal_reason = #{abnormalReason}
  , done_at = #{doneAt}
WHERE id = #{id} AND status = #{from}

mapper.select:
SELECT  FROM settle_item WHERE run_id = #{runId} AND status = 'PENDING'
  AND user_id IN #{u}
ORDER BY user_id, id

SELECT  FROM settle_refund_item WHERE run_id = #{runId} AND status = 'PENDING'
  AND user_id IN #{u}
ORDER BY user_id, id

SELECT  FROM settle_refund_item
WHERE bet_id IN #{b}
ORDER BY user_id, id
